def hidden_rule_fn(state):
    from collections import defaultdict

    n = 8  # grid size

    # Group particles by type
    zex_particles = [p for p in state if p['type'] == 'ZEX']
    glorp_particles = [p for p in state if p['type'] == 'GLORP']

    def toroidal_delta(a, b):
        """Signed toroidal delta from a to b on size n."""
        d = (b - a) % n
        if d > n // 2:
            d -= n
        return d

    def chromodistance(p, q):
        """chromodistance between particles p and q."""
        dx = abs(toroidal_delta(p['x'], q['x']))
        dy = abs(toroidal_delta(p['y'], q['y']))
        d = max(dx, dy)
        if p['type'] != q['type']:
            d += 1
        return d

    def nearest_by_chromo(source, candidates, include_same_type=True):
        """Find the candidate with minimum chromodistance.
        Tiebreak: lexicographically smallest (x, y)."""
        filtered = candidates if include_same_type else [c for c in candidates if c['type'] != source['type']]
        if not filtered:
            return source  # no valid target, stay
        best = None
        best_d = float('inf')
        for c in filtered:
            d = chromodistance(source, c)
            if d < best_d or (d == best_d and (c['x'], c['y']) < (best['x'], best['y'])):
                best_d = d
                best = c
        return best

    def move_one_step_toward(origin, target):
        """Move one step from origin toward target along dominant axis."""
        dx = toroidal_delta(origin['x'], target['x'])
        dy = toroidal_delta(origin['y'], target['y'])

        if abs(dx) >= abs(dy):
            # Move along x-axis
            if dx != 0:
                new_x = (origin['x'] + (1 if dx > 0 else -1)) % n
            else:
                new_x = origin['x']
            new_y = origin['y']
        else:
            # Move along y-axis
            new_x = origin['x']
            if dy != 0:
                new_y = (origin['y'] + (1 if dy > 0 else -1)) % n
            else:
                new_y = origin['y']
        return {'type': origin['type'], 'x': new_x, 'y': new_y}

    def move_one_step_away(origin, target):
        """Move one step from origin away from target along axis with larger magnitude delta.
        X-axis preferred on tie."""
        dx = toroidal_delta(origin['x'], target['x'])
        dy = toroidal_delta(origin['y'], target['y'])

        if abs(dx) > abs(dy):
            # Move along x-axis away
            if dx != 0:
                new_x = (origin['x'] - (1 if dx > 0 else -1)) % n
            else:
                new_x = origin['x']
            new_y = origin['y']
        elif abs(dx) < abs(dy):
            # Move along y-axis away
            new_x = origin['x']
            if dy != 0:
                new_y = (origin['y'] - (1 if dy > 0 else -1)) % n
            else:
                new_y = origin['y']
        else:
            # Tie: x-axis preferred
            if dx != 0:
                new_x = (origin['x'] - (1 if dx > 0 else -1)) % n
            else:
                new_x = origin['x']
            new_y = origin['y']
        return {'type': origin['type'], 'x': new_x, 'y': new_y}

    result = []
    for p in state:
        if p['type'] == 'ZEX':
            # Find nearest ZEX partner (exclude self)
            other_zex = [z for z in zex_particles if z['x'] != p['x'] or z['y'] != p['y']]
            if other_zex:
                target = nearest_by_chromo(p, other_zex, include_same_type=True)
                result.append(move_one_step_toward(p, target))
            else:
                result.append({'type': p['type'], 'x': p['x'], 'y': p['y']})
        elif p['type'] == 'GLORP':
            # Find nearest ZEX (all ZEX particles)
            if zex_particles:
                target = nearest_by_chromo(p, zex_particles, include_same_type=False)
                result.append(move_one_step_away(p, target))
            else:
                result.append({'type': p['type'], 'x': p['x'], 'y': p['y']})
        else:
            result.append({'type': p['type'], 'x': p['x'], 'y': p['y']})

    return result
